"""Install the shared BitmapResource layout (worktree root).

argv[1]: comma-separated functions to keep in 'minimal' form (shared type, original
address arithmetic); every other site gets typed indexing.
"""
import re, sys
from pathlib import Path

MIN = set(filter(None, (sys.argv[1] if len(sys.argv) > 1 else '').split(',')))

def must(t, old, new, n=1):
    assert t.count(old) == n, (old[:70], t.count(old), n)
    return t.replace(old, new)

def block(t, name):
    m = re.search(r'/\* fzgx:begin ' + name + r'( [^*]*)?\*/', t)
    e = t.index('/* fzgx:end ' + name + ' */', m.start())
    return m.start(), e

def edit(t, name, typed, minimal=None):
    s, e = block(t, name)
    b = t[s:e]
    for old, new, *n in (minimal if name in MIN and minimal is not None else typed):
        b = must(b, old, new, n[0] if n else 1)
    return t[:s] + b + t[e:]

Path('include/rel/main_rel/bitmap_resource.h').write_text('''#ifndef REL_MAIN_REL_BITMAP_RESOURCE_H
#define REL_MAIN_REL_BITMAP_RESOURCE_H

#include "types.h"

/* Bitmap resource table lbl_1_data_FCD4[188], 0x28 bytes each.
 * Retail data gives each record seven archive paths selected by the language
 * index lbl_801A66B4. The loader fn_1_47AD4 records the heap index (an entry of
 * the three-heap table lbl_1_data_6CA0) and the image set: 0x10-byte texture
 * headers plus 0x20-byte texture objects initialized with GXInitTexObj. */
typedef struct BitmapImageInfo {
    u32 flags;
    u32 offset;
    u16 width;
    u16 height;
    u32 unk_C;
} BitmapImageInfo;

typedef struct BitmapImages {
    u32 count;
    BitmapImageInfo *info;
    u32 unk_8;
    u32 (*textures)[8];
} BitmapImages;

typedef struct BitmapResource {
    s32 loaded;
    char *paths[7];
    BitmapImages *images;
    u8 heap;
    u8 pad_25[3];
} BitmapResource;

extern BitmapResource lbl_1_data_FCD4[188];

#endif
''')

GEN = re.compile(r'// lbl_1_data_FCD4: [^\n]*\ntypedef struct \{\n    u8 pad_0\[0x4\];\n    u32 unk_4;[^\n]*\n'
                 r'    u8 pad_8\[0x4\];\n    u32 unk_C;[^\n]*\n\} Obj_1_data_FCD4_At20;\ntypedef struct \{\n'
                 r'    u32 unk_0;[^\n]*\n    u32 unk_4;[^\n]*\n    u8 pad_8\[0x18\];\n    Obj_1_data_FCD4_At20 \*unk_20;[^\n]*\n'
                 r'    u8 unk_24;[^\n]*\n    u8 pad_25\[0x1D3B\];\n\} Obj_1_data_FCD4;\nextern Obj_1_data_FCD4 lbl_1_data_FCD4;\n')
for h in ('bitmap', 'font', 'ranking'):
    p = Path(f'include/rel/main_rel/{h}.h'); t = p.read_text()
    t, n = GEN.subn('// lbl_1_data_FCD4: .data size 0x1D60 (188 x 0x28)\n#include "rel/main_rel/bitmap_resource.h"\n', t)
    assert n == 1, h
    p.write_text(t)

R = 'BitmapResource'
# ---------------- bitmap.c
p = Path('src/rel/main_rel/bitmap.c'); t = p.read_text()
t = edit(t, 'fn_1_47E54', [
    ('typedef struct {\n    s32 unk_0;\n    s32 unk_4[9];\n} Fn147E54Entry;\n\n', ''),
    ('extern void fn_1_465D0(s32, s32);', 'extern void fn_1_465D0(char *, s32);'),
    ('fn_1_465D0(*(s32 *)((u8 *)&lbl_1_data_FCD4.unk_4 + index * 0x28 + lbl_801A66B4 * 4), 1);',
     'fn_1_465D0(lbl_1_data_FCD4[index].paths[lbl_801A66B4], 1);')], [
    ('typedef struct {\n    s32 unk_0;\n    s32 unk_4[9];\n} Fn147E54Entry;\n\n', ''),
    ('fn_1_465D0(*(s32 *)((u8 *)&lbl_1_data_FCD4.unk_4 + index * 0x28 + lbl_801A66B4 * 4), 1);',
     'fn_1_465D0(*(s32 *)((u8 *)lbl_1_data_FCD4[0].paths + index * 0x28 + lbl_801A66B4 * 4), 1);')])
for fn, ty in (('fn_1_47EE4', 'Fn147EE4Entry'), ('fn_1_47F74', 'Fn147F74Entry'), ('fn_1_48004', 'BitmapEntry')):
    var = 'entry' if fn == 'fn_1_48004' else 'object'
    common = [(f'typedef struct {{\n    s32 unk_0;\n    u8 pad_4[0x24];\n}} {ty};\n\n', ''),
              (f'{ty} *', f'{R} *', 2),
              (f'{var}->unk_0', f'{var}->loaded', 1 if fn != 'fn_1_48004' else 2)]
    t = edit(t, fn, [(f'{var} = ({ty} *)((u8 *)&lbl_1_data_FCD4 + index * 0x28);', f'{var} = &lbl_1_data_FCD4[index];')] + common,
