    ('record = (TexRecord *)((u8 *)&lbl_1_data_FCD4 + i * 0x28);', 'record = &lbl_1_data_FCD4[i];'),
    ('scan = (TexRecord *)((u8 *)&lbl_1_data_FCD4 + n * 0x28);', 'scan = &lbl_1_data_FCD4[n];'),
    ('record = (TexRecord *)((u8 *)record + 0x28);', 'record++;'),
