    ('record->unk_0', 'record->loaded', 3), ('scan->unk_0', 'scan->loaded'),
    ('record->unk_24', 'record->heap', 4), ('scan->unk_24', 'scan->heap'),
    ('record->unk_20->unk_C', '(u32)record->images->textures', 2), ('(u32)record->unk_20', '(u32)record->images', 2)])
t = edit(t, 'fn_1_484CC', [
    ('u8 *texture_record;', f'{R} *texture_record;'),
