    ('*(s32 *)texture_record != 0 && texture_record[0x24] == index', 'texture_record->loaded != 0 && texture_record->heap == index'),
    ('texture_record += 0x28;', 'texture_record++;')])
t = edit(t, 'fn_1_485A8', [
    ('return ((Obj_1_data_FCD4 *)((u8 *)&lbl_1_data_FCD4 + index * 0x28))->unk_0 != 0;', 'return lbl_1_data_FCD4[index].loaded != 0;')])
t = edit(t, 'fn_1_485C8', [
    ('''extern struct fn_1_485C8_lbl_1_data_FCD4 lbl_1_data_FCD4;
extern u32 lbl_1_bss_3E020;

struct fn_1_485C8_lbl_1_data_FCD4_0_E40 {
