    ('lbl_1_bss_3E020 = lbl_1_data_FCD4.unk_0[arg0].unk_20;', 'lbl_1_bss_3E020 = (u32)lbl_1_data_FCD4[arg0].images;')])
t = edit(t, 'fn_1_48730', [
    ('''    Obj_1_data_FCD4 *entry =
        (Obj_1_data_FCD4 *)((u8 *)&lbl_1_data_FCD4 + table_index * 0x28);''', f'    {R} *entry = &lbl_1_data_FCD4[table_index];'),
    ('(s32)entry->unk_0 == 1 && entry->unk_20 != 0', 'entry->loaded == 1 && entry->images != 0'),
    ('return (u8 *)entry->unk_20->unk_4 + ((u8)slot_index << 4);', 'return &entry->images->info[(u8)slot_index];')])
t = edit(t, 'fn_1_48780', [
    ('Obj_1_data_FCD4 *obj;', f'{R} *obj;'),
    ('obj = (Obj_1_data_FCD4 *)((u8 *)&lbl_1_data_FCD4 + 0x28);', 'obj = &lbl_1_data_FCD4[1];'),
    ('(int)obj->unk_0 != 0', 'obj->loaded != 0'), ('fn_1_47AD4(obj, obj->unk_24, 0, 0);', 'fn_1_47AD4(obj, obj->heap, 0, 0);'),
    ('obj = (Obj_1_data_FCD4 *)((u8 *)obj + 0x28);', 'obj++;')])
t = edit(t, 'fn_1_487EC', [('extern void fn_1_47AD4(Obj_1_data_FCD4 *obj,', f'extern void fn_1_47AD4({R} *obj,', 2)])
pro = t.index('/* fzgx:begin ')
t = must(t[:pro], 'extern void fn_1_47AD4(Obj_1_data_FCD4 *obj,', f'extern void fn_1_47AD4({R} *obj,') + t[pro:]
assert 'Obj_1_data_FCD4' not in t, [m.start() for m in re.finditer('Obj_1_data_FCD4', t)][:5]
p.write_text(t)

# ---------------- ranking.c
p = Path('src/rel/main_rel/ranking.c'); t = p.read_text()
t = edit(t, 'fn_1_159588', [
