"""fn_1_527B4 typed entry variants under BitmapResource; two fixed variants once."""
import sys, json
from pathlib import Path
sys.path.insert(0, 'tools')
from fzgx import api, fixup, oracle
from fzgx.project import Project
p = Project('GFZE01'); out = Path('.fzgx/manual-device-review/bitmap-resource/fn_1_527B4'); e = fixup.Engine(p, out)
key = 'main_rel:fn_1_527B4'; s = p.resolve(key); mw, flags = oracle.version_for(p, s)
body = api._canonical_text(p, p.unit_record(p.unit_of(s))['source'])
old = '''        index = ((value >> 8) & 0xffff) * 0x28;
        entry = (BitmapResource *)lbl_1_data_FCD4;
        entry = (BitmapResource *)((u8 *)entry + index);
'''
assert old in body
V = [('''        index = (value >> 8) & 0xffff;
        entry = &lbl_1_data_FCD4[index];
''', 'element index temporary'),
     ('''        index = (value >> 8) & 0xffff;
        entry = lbl_1_data_FCD4;
        entry += index;
''', 'base then advance')]
rows = [e.record(key, body, mw, flags, label='installed minimal control')]
rows += [e.record(key, body.replace(old, n), mw, flags, parent=rows[0]['id'], label=l) for n, l in V]
with oracle.build_lock(): e.evaluate(rows)
report = dict(hypothesis=__doc__.strip(), stopping_condition='two fixed variants once', records=rows, best={},
              frontier={'all_frozen_probes': rows}, generator_sha256=e.generator_sha256, environment=e.environment)
(out / 'report.json').write_text(json.dumps(report, indent=2) + '\n'); fixup.archive_sources(report, out / 'sources.json.gz')
for r in rows: print(r['sha256'][:12], bool(r.get('matched')), r.get('word_errors'), r['label'])
